PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS admins(id INTEGER PRIMARY KEY AUTOINCREMENT,username TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions(id INTEGER PRIMARY KEY AUTOINCREMENT,token TEXT NOT NULL UNIQUE,admin_id INTEGER NOT NULL,expires_at TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(admin_id) REFERENCES admins(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS bots(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,username TEXT,token TEXT NOT NULL UNIQUE,telegram_id INTEGER,status INTEGER NOT NULL DEFAULT 1,webhook_url TEXT,description TEXT DEFAULT '',short_description TEXT DEFAULT '',photo_file_id TEXT,last_error TEXT,last_checked_at TEXT,last_activity_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS telegram_users(id INTEGER PRIMARY KEY AUTOINCREMENT,bot_id INTEGER NOT NULL,telegram_id INTEGER NOT NULL,username TEXT,first_name TEXT,last_name TEXT,start_parameter TEXT,is_blocked INTEGER NOT NULL DEFAULT 0,first_seen TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,last_seen TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(bot_id,telegram_id),FOREIGN KEY(bot_id) REFERENCES bots(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS bot_homepage(id INTEGER PRIMARY KEY AUTOINCREMENT,bot_id INTEGER NOT NULL UNIQUE,text TEXT DEFAULT '',photo_file_id TEXT,video_file_id TEXT,parse_mode TEXT DEFAULT 'HTML',FOREIGN KEY(bot_id) REFERENCES bots(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS reply_buttons(id INTEGER PRIMARY KEY AUTOINCREMENT,bot_id INTEGER NOT NULL,text TEXT NOT NULL,url TEXT NOT NULL,row_number INTEGER NOT NULL DEFAULT 0,position INTEGER NOT NULL DEFAULT 0,FOREIGN KEY(bot_id) REFERENCES bots(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS broadcasts(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT,content TEXT,media_type TEXT,media_file_id TEXT,button_json TEXT,target_type TEXT,status TEXT NOT NULL DEFAULT 'pending',total_users INTEGER NOT NULL DEFAULT 0,success_count INTEGER NOT NULL DEFAULT 0,failed_count INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,completed_at TEXT);
CREATE TABLE IF NOT EXISTS broadcast_targets(id INTEGER PRIMARY KEY AUTOINCREMENT,broadcast_id INTEGER NOT NULL,bot_id INTEGER NOT NULL,FOREIGN KEY(broadcast_id) REFERENCES broadcasts(id) ON DELETE CASCADE,FOREIGN KEY(bot_id) REFERENCES bots(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS logs(id INTEGER PRIMARY KEY AUTOINCREMENT,admin_id INTEGER,action TEXT NOT NULL,details TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(admin_id) REFERENCES admins(id) ON DELETE SET NULL);
CREATE INDEX IF NOT EXISTS idx_bots_status ON bots(status); CREATE INDEX IF NOT EXISTS idx_users_bot ON telegram_users(bot_id); CREATE INDEX IF NOT EXISTS idx_users_seen ON telegram_users(last_seen); CREATE INDEX IF NOT EXISTS idx_logs_created ON logs(created_at);

CREATE TABLE IF NOT EXISTS bot_commands(id INTEGER PRIMARY KEY AUTOINCREMENT,bot_id INTEGER NOT NULL,command TEXT NOT NULL,description TEXT NOT NULL,response_text TEXT DEFAULT '',UNIQUE(bot_id,command),FOREIGN KEY(bot_id) REFERENCES bots(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_bot_commands_bot ON bot_commands(bot_id);

